function loadState(){
  try {
    const saved=JSON.parse(localStorage.getItem(STORAGE_KEY))||{};
    const loaded={clients:[],projects:[],transactions:[],budgets:[],supplierQuotes:[],fixedCosts:[],appointments:[],employees:[],workLogs:[],employeeAdvances:[],employeePayments:[],...saved};
    const legacyStatus={"Em preparação":"Em análise","Enviado":"Em análise"};
    loaded.budgets=(loaded.budgets||[]).map(b=>({...b,status:legacyStatus[b.status]||b.status||"Em análise",history:Array.isArray(b.history)?b.history:[]}));
    loaded.employees=(loaded.employees||[]).map(e=>({...e,overtimeMode:e.overtimeMode||"weekly",weeklyHoursLimit:e.weeklyHoursLimit||44}));
    return loaded;
  }
  catch { return {clients:[],projects:[],transactions:[],budgets:[],supplierQuotes:[],fixedCosts:[],appointments:[],employees:[],workLogs:[],employeeAdvances:[],employeePayments:[]}; }
}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function esc(value=""){return String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function money(value){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(Number(value)||0);}
function safeHttpUrl(value){try{const url=new URL(value);return url.protocol==="https:"||url.protocol==="http:"?url.href:"";}catch{return "";}}
function dateBR(value){if(!value)return "—";const d=new Date(`${value}T12:00:00`);return Number.isNaN(d.getTime())?"—":d.toLocaleDateString("pt-BR");}
function todayISO(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");}
function clientName(id){return state.clients.find(c=>c.id===id)?.name||"Cliente sem cadastro";}
function projectProgress(project){const i=STAGES.indexOf(project.stage||STAGES[0]);return Math.round((Math.max(0,i)/(STAGES.length-1))*100);}
