function logOvertimeHours(log,timeByLog=weeklyTimeByLog()){const e=state.employees.find(x=>x.id===log.employeeId);return e?.overtimeMode==="weekly"?(timeByLog.get(log.id)?.overtimeHours||0):workLogAmounts(log).overtime;}
function logRegularExtraHours(log,timeByLog=weeklyTimeByLog()){const e=state.employees.find(x=>x.id===log.employeeId);return e?.overtimeMode==="weekly"?(timeByLog.get(log.id)?.regularExtraHours||0):0;}
function logRegularExtraPay(log,timeByLog=weeklyTimeByLog()){const e=state.employees.find(x=>x.id===log.employeeId);return logRegularExtraHours(log,timeByLog)*(Number(e?.dailyRate)||0)/(Number(e?.standardHours)||8);}
function logOvertimePay(log,timeByLog=weeklyTimeByLog()){const e=state.employees.find(x=>x.id===log.employeeId);if(!e)return 0;return logOvertimeHours(log,timeByLog)*(Number(e.dailyRate)||0)/(Number(e.standardHours)||8)*(1+(Number(e.overtimePercent??50)/100));}
function employeeAccruedForLogs(logs,allLogs=state.workLogs||[]){const timeByLog=weeklyTimeByLog(allLogs);let base=logs.reduce((sum,l)=>sum+workLogAmounts(l).total+((state.employees.find(e=>e.id===l.employeeId)?.overtimeMode)==="weekly"?logRegularExtraPay(l,timeByLog)+logOvertimePay(l,timeByLog):0),0),groups=new Set();for(const log of logs){const employee=state.employees.find(e=>e.id===log.employeeId),frequency=employee?.passageFrequency||"day",amount=Number(employee?.passageAmount??employee?.passagePerDay)||0;if(!employee||frequency==="day"||amount<=0||!log.date)continue;const d=new Date(`${log.date}T12:00:00`),ym=log.date.slice(0,7),weekStart=new Date(d);weekStart.setDate(d.getDate()-((d.getDay()+6)%7));const key=frequency==="week"?`${employee.id}:w:${weekStart.toISOString().slice(0,10)}`:frequency==="fortnight"?`${employee.id}:f:${ym}:${d.getDate()<=15?1:2}`:frequency==="month"?`${employee.id}:m:${ym}`:"";if(key)groups.add(key);}for(const key of groups){const employee=state.employees.find(e=>key.startsWith(`${e.id}:`));base+=Number(employee?.passageAmount)||0;}return base;}
function payrollAccruedForMonth(ym){return employeeAccruedForLogs((state.workLogs||[]).filter(l=>(l.date||"").slice(0,7)===ym));}
function payrollCashForMonth(ym){return (state.transactions||[]).filter(t=>t.type==="saída"&&t.payroll===true&&(t.date||"").slice(0,7)===ym).reduce((sum,t)=>sum+Number(t.amount||0),0);}
function dreForYear(year){const months=Array.from({length:12},(_,i)=>{const ym=`${year}-${String(i+1).padStart(2,"0")}`,tx=state.transactions.filter(t=>(t.date||"").slice(0,7)===ym),revenue=tx.filter(t=>t.type==="entrada").reduce((s,t)=>s+Number(t.amount||0),0),expenses=tx.filter(t=>t.type==="saída"),payroll=payrollAccruedForMonth(ym),variable=expenses.filter(t=>t.category!=="Escritório / custo fixo"&&!t.payroll).reduce((s,t)=>s+Number(t.amount||0),0)+payroll,recordedFixed=expenses.filter(t=>t.category==="Escritório / custo fixo").reduce((s,t)=>s+Number(t.amount||0),0),scheduledFixed=fixedCostsForMonth(ym),fixed=recordedFixed+scheduledFixed,contribution=revenue-variable,profit=contribution-fixed;return {ym,revenue,variable,payroll,recordedFixed,scheduledFixed,fixed,contribution,contributionRate:revenue?contribution/revenue*100:0,profit};});const totals=months.reduce((a,m)=>{for(const key of ["revenue","variable","payroll","recordedFixed","scheduledFixed","fixed","contribution","profit"])a[key]+=m[key];return a;},{revenue:0,variable:0,payroll:0,recordedFixed:0,scheduledFixed:0,fixed:0,contribution:0,profit:0});totals.contributionRate=totals.revenue?totals.contribution/totals.revenue*100:0;return {months,totals};}
function dreChartSvg(months){const width=960,height=285,left=48,right=14,top=18,bottom=38,plotWidth=width-left-right,plotHeight=height-top-bottom,series=[{key:"revenue",color:"#4f8b6a"},{key:"contribution",color:"#d6a24b"},{key:"profit",color:"#183f35"}],values=months.flatMap(m=>series.map(s=>m[s.key])),max=Math.max(1,...values),min=Math.min(0,...values),range=max-min||1,y=value=>top+(max-value)/range*plotHeight,zeroY=y(0),groupWidth=plotWidth/12,barWidth=Math.min(12,groupWidth/5),gap=3,grid=Array.from({length:5},(_,i)=>{const value=max-(range*i/4),gy=y(value),label=value===0?"R$ 0":money(value);return `<g><line x1="${left}" y1="${gy}" x2="${width-right}" y2="${gy}" stroke="#e9edeb"/><text x="${left-6}" y="${gy+3}" text-anchor="end" fill="#849089" font-size="9">${esc(label)}</text></g>`}).join(""),bars=months.map((month,i)=>{const center=left+groupWidth*(i+.5),totalWidth=series.length*barWidth+(series.length-1)*gap;const rects=series.map((s,j)=>{const value=month[s.key],endY=y(value),rectY=Math.min(zeroY,endY),rectH=Math.max(1,Math.abs(zeroY-endY)),x=center-totalWidth/2+j*(barWidth+gap);return `<rect x="${x}" y="${rectY}" width="${barWidth}" height="${rectH}" rx="2" fill="${s.color}"><title>${esc(month.ym)} · ${s.key==="revenue"?"Receita":s.key==="contribution"?"Margem de contribuição":"Lucro operacional"}: ${esc(money(value))}</title></rect>`}).join(""),label=new Date(Number(month.ym.slice(0,4)),Number(month.ym.slice(5,7))-1,1).toLocaleDateString("pt-BR",{month:"short"}).replace(".","");return `${rects}<text x="${center}" y="${height-12}" text-anchor="middle" fill="#738079" font-size="10">${esc(label)}</text>`}).join("");return `<svg class="dre-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Gráfico mensal de receita, margem de contribuição e lucro operacional">${grid}${bars}<line x1="${left}" y1="${zeroY}" x2="${width-right}" y2="${zeroY}" stroke="#98a59d" stroke-width="1.2"/></svg>`;}
