 modal(`Histórico · ${esc(budget.projectName)}`,`${esc(clientName(budget.clientId))} · proposta de ${money(budget.amount)}`,`<div class="timeline">${history.map((item,i)=>`<div class="timeline-row ${i===history.length-1?"current":"done"}"><span class="timeline-marker">${i+1}</span><div><b>${esc(item.status)}</b><small>${dateBR(item.date)} · ${esc(item.detail||"Atualização registrada")}</small></div></div>`).join("")}</div>${budget.convertedProjectId?`<div class="note-box" style="margin-top:14px">Cliente convertido em projeto em ${dateBR(budget.convertedAt||"")}.</div>`:""}`,`<button class="btn primary" data-close="true">Fechar</button>`);
