function openSupplierQuoteModal(prefill=null){
 const initialItems=prefill?.items?.length?prefill.items:[{}];
 modal("Registrar cotação de material","Confira e ajuste os dados antes de salvar; o acréscimo de 20% é calculado automaticamente.",`<div class="form-grid">${field("Fornecedor","supplierName","Nome da loja ou fornecedor","text",true,prefill?.supplier||"")}${field("Data da cotação","supplierDate","","date",true,prefill?(prefill.date||""):todayISO())}${field("Região de fornecimento","supplierRegion","Rio de Janeiro/RJ","text",false,prefill?(prefill.region||""):"Rio de Janeiro/RJ")}<div class="field full"><label for="supplierPdfFile">PDF recebido (referência)</label><input id="supplierPdfFile" type="file" accept="application/pdf"><input id="supplierDocumentRef" type="hidden" value="${esc(prefill?.documentName||"")}"><small>O aplicativo guarda somente o nome como referência; não arquiva o PDF.</small></div><div class="field full">${field("Link da cotação ou produto","supplierSource","https://...","url")}</div></div><div class="section-head" style="margin-top:18px"><div><h3 style="margin:0">Itens cotados</h3><div class="project-sub">Confira as descrições, quantidades e preços extraídos.</div></div><button class="btn small" type="button" id="addQuoteLine">＋ Adicionar item</button></div><div id="supplierQuoteLines">${initialItems.map((item,i)=>supplierQuoteLine(i,item)).join("")}</div><div class="quote-total" id="supplierQuoteTotal">Total-base: ${money(0)} · com ${MATERIAL_BUFFER_PERCENT}%: ${money(0)}</div><p class="disclaimer">O preço-base ficará preservado. Os ${MATERIAL_BUFFER_PERCENT}% são um acréscimo de orçamento sobre cada insumo, não a margem final da obra.</p>`,`<button class="btn" data-close="true">Cancelar</button><button class="btn primary" id="saveSupplierQuote">Salvar cotação</button>`);
 const lines=document.getElementById("supplierQuoteLines");
 const updateTotal=()=>{let total=0;lines.querySelectorAll("[data-quote-line]").forEach(row=>{total+=(Number(row.querySelector("[data-line-quantity]").value)||0)*(Number(row.querySelector("[data-line-cost]").value)||0);});document.getElementById("supplierQuoteTotal").textContent=`Total-base: ${money(total)} · com ${MATERIAL_BUFFER_PERCENT}%: ${money(total*(1+MATERIAL_BUFFER_PERCENT/100))}`;};
 document.getElementById("addQuoteLine").onclick=()=>{lines.insertAdjacentHTML("beforeend",supplierQuoteLine(lines.querySelectorAll("[data-quote-line]").length));updateTotal();};
 lines.addEventListener("input",updateTotal);lines.addEventListener("change",updateTotal);
 lines.addEventListener("click",e=>{const button=e.target.closest("[data-remove-line]");if(!button)return;if(lines.querySelectorAll("[data-quote-line]").length<=1)return showToast("A cotação precisa ter pelo menos um item.");button.closest("[data-quote-line]").remove();updateTotal();});
 document.getElementById("saveSupplierQuote").onclick=()=>{
  const supplier=document.getElementById("supplierName").value.trim(),date=document.getElementById("supplierDate").value,region=document.getElementById("supplierRegion").value.trim(),file=document.getElementById("supplierPdfFile").files[0],documentName=file?.name||document.getElementById("supplierDocumentRef").value||"",sourceUrl=safeHttpUrl(document.getElementById("supplierSource").value.trim());
  const items=[...lines.querySelectorAll("[data-quote-line]")].map(row=>({description:row.querySelector("[data-line-description]").value.trim(),category:row.querySelector("[data-line-category]").value,quantity:Number(row.querySelector("[data-line-quantity]").value),unit:row.querySelector("[data-line-unit]").value.trim()||"un",unitCost:Number(row.querySelector("[data-line-cost]").value)}));
  if(!supplier||!date)return showToast("Informe fornecedor e data da cotação.");
  if(items.some(x=>!x.description||x.quantity<=0||x.unitCost<=0))return showToast("Preencha descrição, quantidade e preço de cada item.");
  const duplicate=(state.supplierQuotes||[]).some(q=>documentName&&q.documentName===documentName&&q.supplier.toLowerCase()===supplier.toLowerCase()&&q.date===date);
  if(duplicate)return showToast("Esse PDF, fornecedor e data já estão registrados.");
  state.supplierQuotes.push({id:crypto.randomUUID(),supplier,region,date,documentName,sourceUrl,items,createdAt:new Date().toISOString()});
  save();closeModal();currentView="quotes";render();showToast("Cotação registrada; preços-base e acréscimo salvos.");
 };
}
function supplierQuoteLine(index,item={}){
 const categories=["MDF","Dobradiça","Ferragem","Parafuso","Fita de LED","Perfil de LED","Vidro","Serralheria","Outro"];
 const category=categories.includes(item.category)?item.category:"Outro";
 return `<div class="quote-line" data-quote-line><div class="field"><label>Material / especificação *</label><input data-line-description placeholder="Ex.: MDF Carvalho 18 mm" required value="${esc(item.description||"")}"></div><div class="field"><label>Categoria</label><select data-line-category>${categories.map(c=>`<option ${c===category?"selected":""}>${esc(c)}</option>`).join("")}</select></div><div class="field"><label>Quantidade</label><input data-line-quantity type="number" min="0.01" step="0.01" value="${Number(item.quantity)||1}"></div><div class="field"><label>Unidade</label><input data-line-unit value="${esc(item.unit||"un")}" placeholder="chapa, un, m, m²"></div><div class="field"><label>Preço unitário (R$) *</label><input data-line-cost type="number" min="0.01" step="0.01" placeholder="0,00" required value="${Number(item.unitPrice)||""}"></div><button class="btn small quote-line-remove" type="button" data-remove-line aria-label="Remover material ${index+1}">Remover</button></div>`;
}
function openPdfAnalyzeModal(){
 modal("Analisar PDF com IA","Extraia dados de uma cotação ou uma lista preliminar de materiais de projeto.",`<div class="form-grid"><div class="field full"><label for="aiPdfKind">Tipo de documento</label><select id="aiPdfKind"><option value="supplier_quote">Cotação de fornecedor (com preços)</option><option value="project_materials">Projeto ou lista de materiais (rascunho)</option></select></div><div class="field full"><label for="aiPdfFile">Arquivo PDF *</label><input id="aiPdfFile" type="file" accept="application/pdf, .pdf" required><small>Limite do protótipo: 10 MB por arquivo PDF.</small></div><label class="ai-consent field full"><input id="aiUploadConsent" type="checkbox"><span>Entendo que este PDF será enviado à OpenAI API para análise. Vou revisar os dados extraídos antes de salvá-los.</span></label></div><div class="note-box" style="margin-top:14px">Não inclua documentos sem autorização. O servidor do protótipo não arquiva o arquivo, mas a análise é processada pela OpenAI API e pode gerar cobrança de uso na conta configurada.</div><div id="aiPdfStatus" class="ai-status" role="status"></div>`,`<button class="btn" data-close="true">Cancelar</button><button class="btn primary" id="runPdfAnalysis">Analisar PDF</button>`);
 document.getElementById("runPdfAnalysis").onclick=analyzePdf;
}
async function analyzePdf(){
 const file=document.getElementById("aiPdfFile").files[0],kind=document.getElementById("aiPdfKind").value,consent=document.getElementById("aiUploadConsent").checked,status=document.getElementById("aiPdfStatus"),button=document.getElementById("runPdfAnalysis");
 if(!file)return showToast("Selecione um arquivo PDF.");if(file.size>10*1024*1024)return showToast("O PDF deve ter no máximo 10 MB.");if(!file.name.toLowerCase().endsWith(".pdf")||file.type&&file.type!=="application/pdf")return showToast("Selecione um arquivo PDF válido.");if(!consent)return showToast("Confirme o envio do arquivo à OpenAI API.");
 button.disabled=true;status.textContent="Enviando o documento para análise…";
 try{
  const bytes=new Uint8Array(await file.arrayBuffer());if(bytes[0]!==0x25||bytes[1]!==0x50||bytes[2]!==0x44||bytes[3]!==0x46)throw new Error("O arquivo selecionado não parece ser um PDF válido.");
  let binary="";for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));
  const response=await fetch("https://oficina-marcenaria-pdf-ia.onrender.com/api/analyze-pdf",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind,filename:file.name,fileData:btoa(binary)})});
  const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`Erro do serviço (${response.status}).`);
  renderPdfAnalysisResult(payload,kind,file.name);
 }catch(error){status.textContent=error.message||"Não foi possível analisar o PDF.";button.disabled=false;}
}
function renderPdfAnalysisResult(result,kind,filename){
 const data=result.extraction||{};const items=Array.isArray(data.items)?data.items:[];const isQuote=kind==="supplier_quote";let lastAnalysis={kind,filename,data};
 const cells=items.map((item,i)=>`<tr><td>${i+1}</td><td><strong>${esc(item.description||"Não identificado")}</strong>${item.specification?`<div class="project-sub">${esc(item.specification)}</div>`:""}</td><td>${esc(item.category||"Não informado")}</td><td>${item.quantity==null?"A confirmar":Number(item.quantity)} ${esc(item.unit||"")}</td><td>${isQuote&&item.unitPrice!=null?money(item.unitPrice):"A confirmar"}</td><td>${esc(item.evidence||"—")}</td></tr>`).join("");
 const meta=isQuote?`<div class="detail-grid"><div class="detail-tile"><label>FORNECEDOR</label><strong>${esc(data.supplier||"A confirmar")}</strong></div><div class="detail-tile"><label>DATA DA COTAÇÃO</label><strong>${esc(data.quoteDate||"A confirmar")}</strong></div></div>`:`<div class="note-box">Lista preliminar extraída do projeto. Ela não substitui conferência técnica, medição de chapas, plano de corte ou cotação com fornecedor.</div>`;
 modal("Resultado da leitura por IA",`Arquivo: ${esc(filename)} · revise todos os campos antes de usar.`,`${meta}<div class="ai-result-summary"><b>${items.length} itens identificados</b><span>${esc(data.notes||"Campos ausentes foram mantidos como ‘a confirmar’.")}</span></div><div class="table-wrap"><table class="ai-result-table"><thead><tr><th>#</th><th>Material / especificação</th><th>Categoria</th><th>Quantidade</th><th>Preço unitário</th><th>Referência no PDF</th></tr></thead><tbody>${cells||`<tr><td colspan="6">Nenhum item foi identificado com segurança. Confira o PDF e tente novamente ou preencha manualmente.</td></tr>`}</tbody></table></div><p class="disclaimer">${isQuote?"A IA extraiu os preços que parecem estar escritos no documento; confirme unidade, quantidade, valor e fornecedor. Nada foi salvo ainda.":"Nenhuma compra, preço ou quantidade foi confirmado pelo sistema. Revise o desenho e use esta lista apenas como rascunho."}</p>`,`<button class="btn" data-close="true">Fechar</button>${isQuote&&items.length?`<button class="btn primary" id="reviewAiQuote">Revisar e registrar cotação</button>`:""}`);
 document.getElementById("reviewAiQuote")?.addEventListener("click",()=>{
  const cleanItems=items.filter(x=>x.description).map(x=>({description:x.description,category:x.category,quantity:Number(x.quantity)||1,unit:x.unit||"un",unitPrice:Number(x.unitPrice)||0}));
  openSupplierQuoteModal({supplier:data.supplier||"",date:/^\d{4}-\d{2}-\d{2}$/.test(data.quoteDate||"")?data.quoteDate:"",region:data.region||"",documentName:filename,items:cleanItems});
 });
}
