function openAppointmentModal(id=null,preferredProjectId=""){
 state.appointments=state.appointments||[];
 const existing=id?state.appointments.find(a=>a.id===id):null;if(id&&!existing)return;
 const projectId=existing?.projectId||preferredProjectId||"",projectOptions=state.projects.map(p=>`<option value="${esc(p.id)}" ${projectId===p.id?"selected":""}>${esc(p.name)} · ${esc(clientName(p.clientId))}</option>`).join("");
 const kind=existing?.kind||"Visita técnica";
 modal(existing?"Editar compromisso":"Agendar compromisso","Vincule à obra para que este horário também apareça no projeto. Deixe sem projeto para um compromisso pessoal.",`<div class="form-grid"><div class="field"><label for="apptKind">Tipo *</label><select id="apptKind">${["Visita técnica","Conferência de medidas","Reunião com cliente","Instalação","Outro"].map(x=>`<option ${kind===x?"selected":""}>${x}</option>`).join("")}</select></div><div class="field"><label for="apptProject">Projeto / obra</label><select id="apptProject"><option value="">Agenda pessoal, sem projeto</option>${projectOptions}</select></div>${field("Título do compromisso *","apptTitle","Ex.: Instalação — quarto das crianças","text",true,existing?.title||"")}${field("Data *","apptDate","","date",true,existing?.date||todayISO())}${field("Horário de início *","apptTime","","time",true,existing?.time||"09:00")}${field("Duração em minutos *","apptDuration","60","number",true,existing?.duration||60)}${field("Local / endereço","apptLocation","Endereço do cliente ou local","text",false,existing?.location||"")}<div class="field full"><label for="apptNotes">Observações</label><textarea id="apptNotes" placeholder="Detalhes para a visita ou para a equipe">${esc(existing?.notes||"")}</textarea></div></div><p class="disclaimer">O aplicativo avisa se o horário escolhido se sobrepõe a outro compromisso ainda ativo na sua agenda.</p>`,`<button class="btn" data-close="true">Cancelar</button><button class="btn primary" id="saveAppointment">${existing?"Salvar alterações":"Salvar na agenda"}</button>`);
 document.getElementById("saveAppointment").onclick=()=>{
  const kindValue=document.getElementById("apptKind").value,project=document.getElementById("apptProject").value||null,title=document.getElementById("apptTitle").value.trim(),date=document.getElementById("apptDate").value,time=document.getElementById("apptTime").value,duration=Number(document.getElementById("apptDuration").value),location=document.getElementById("apptLocation").value.trim(),notes=document.getElementById("apptNotes").value.trim();
  if(!title||!date||!time||!Number.isFinite(duration)||duration<=0||duration>1440)return showToast("Informe título, data, horário e duração válida.");
  const start=time.split(":").reduce((h,m)=>h*60+Number(m),0),end=start+duration;
  const conflict=state.appointments.find(a=>a.id!==id&&a.status!=="cancelled"&&a.status!=="done"&&(a.date||"")===date&&(()=>{const aStart=(a.time||"00:00").split(":").reduce((h,m)=>h*60+Number(m),0);return start<aStart+Number(a.duration||60)&&aStart<end;})());
  if(conflict)return showToast(`Conflito com “${conflict.title}” às ${conflict.time}. Escolha outro horário.`);
  const record={id:existing?.id||crypto.randomUUID(),kind:kindValue,projectId:project,clientId:project?appointmentProject(project)?.clientId||null:null,title,date,time,duration,location,notes,status:existing?.status||"scheduled",updatedAt:new Date().toISOString()};
  if(existing)Object.assign(existing,record);else state.appointments.push(record);
  save();closeModal();if(currentView!=="agenda")currentView="agenda";agendaMonth=date.slice(0,7);render();showToast(existing?"Compromisso atualizado.":"Compromisso adicionado à agenda e ao projeto.");
 };
}
