 document.getElementById("saveTransaction").onclick=()=>{const projectId=document.getElementById("txProject").value||null,amountValue=Number(amount.value),description=document.getElementById("txDescription").value.trim(),transactionDate=document.getElementById("txDate").value,kind=type.value,isDaily=kind==="saída"&&category.value==="Diária de mão de obra",workDays=isDaily?Number(days.value)||0:null,dailyRate=isDaily?Number(rate.value)||0:null;if(amountValue<=0||!description||!transactionDate)return showToast("Preencha descrição, data e valor.");if(isDaily&&(!workDays||!dailyRate))return showToast("Informe os dias trabalhados e o valor da diária.");state.transactions.push({id:crypto.randomUUID(),type:kind,projectId,category:category.value,amount:amountValue,date:transactionDate,description,payee:document.getElementById("txPayee").value.trim(),days:workDays,dailyRate});financeMonthFilter=transactionDate.slice(0,7);financeProjectFilter="todos";financeTypeFilter="todos";save();closeModal();render();showToast(projectId?"Lançamento vinculado à obra.":"Lançamento geral registrado.");};
