function openFixedCostModal(id=null){state.fixedCosts=state.fixedCosts||[];const existing=id?state.fixedCosts.find(x=>x.id===id):null;if(id&&!existing)return;const currentMonth=todayISO().slice(0,7);modal(existing?"Editar custo fixo":"Cadastrar custo fixo mensal", "Defina o valor recorrente e o período em que ele entra no fluxo e no DRE.", `<div class="form-grid">${field("Descrição do custo *","fixedCostName","Ex.: Aluguel da oficina","text",true,existing?.name||"")}${field("Valor mensal (R$) *","fixedCostAmount","0,00","number",true,existing?.amount||"")}${field("Começa em *","fixedCostStart","","month",true,existing?.startMonth||currentMonth)}${field("Último mês (opcional)","fixedCostEnd","","month",false,existing?.endMonth||"")}</div><div class="note-box" style="margin-top:14px">O custo será projetado em cada mês do período. Para dar baixa manualmente, use a categoria “Escritório / custo fixo” e repita exatamente esta descrição; assim o lançamento pago substitui a previsão daquele mês.</div>`, `<button class="btn" data-close="true">Cancelar</button><button class="btn primary" id="saveFixedCost">${existing?"Salvar alteração":"Adicionar custo mensal"}</button>`);document.getElementById("saveFixedCost").onclick=()=>{const name=document.getElementById("fixedCostName").value.trim(),amount=Number(document.getElementById("fixedCostAmount").value),startMonth=document.getElementById("fixedCostStart").value,endMonth=document.getElementById("fixedCostEnd").value;if(!name||amount<=0||!startMonth)return showToast("Informe descrição, valor mensal e início.");if(endMonth&&endMonth<startMonth)return showToast("O último mês não pode ser anterior ao início.");if(state.fixedCosts.some(x=>x.id!==id&&x.name.trim().toLocaleLowerCase("pt-BR")===name.toLocaleLowerCase("pt-BR")))return showToast("Use uma descrição diferente para cada custo recorrente.");if(existing)Object.assign(existing,{name,amount,startMonth,endMonth});else state.fixedCosts.push({id:crypto.randomUUID(),name,amount,startMonth,endMonth});save();closeModal();currentView="finance";render();showToast(existing?"Custo fixo atualizado.":"Custo fixo aplicado aos meses do período.");};}
